from pathlib import Path
from datetime import datetime
from zoneinfo import ZoneInfo
import json,hashlib,subprocess,re
ROOT=Path.cwd();REL='reports/research/510300_official_pmi_interpretation_cause_source_qualification_v1';OUT=ROOT/REL
proto=json.loads((OUT/'protocol.json').read_text(encoding='utf-8-sig'))
assert not (OUT/'本地有限旧用途定位.json').exists(),'不重复有限旧用途搜索。'
for r in proto['parents']:assert hashlib.sha256((ROOT/r['path']).read_bytes()).hexdigest()==r['sha256']
patterns=['采购量','需求不足','赵庆河','nbs_review','采购经理指数.*解读']
cmd=['rg','-n','--max-columns','2000','--max-columns-preview','--glob','*.py','--glob','*.json',
 '--glob','!*access*','--glob','!*provider*','--glob','!*credential*','--glob','!*local*',
 '--glob','!*secret*','--glob','!*token*','--glob','!*primary_market*',
 '|'.join(patterns),'research','config']
r=subprocess.run(cmd,cwd=ROOT,capture_output=True,text=True,encoding='utf-8',errors='replace')
assert r.returncode in [0,1],r.stderr[:1000]
lines=r.stdout.splitlines()
matches=[{'locator':x,'status':'KEYWORD_LOCATOR_NOT_PROOF_OF_SAME_USE'} for x in lines]
related=[]
for d in proto['prior_use_search_scope']['scope'][1:]:
 p=ROOT/d
 info={'directory':d,'files':[x.name for x in p.iterdir() if x.is_file()]}
 for n in ['result.json','protocol.json','source_gate.json']:
  f=p/n
  if f.exists():
   obj=json.loads(f.read_text(encoding='utf-8-sig'))
   # 只读取直接研究入口；递归定位报告中的解读/原因来源引用。
   found=[]
   def walk(x,path):
    if isinstance(x,dict):
     for k,v in x.items():walk(v,path+'.'+k)
    elif isinstance(x,list):
     for i,v in enumerate(x):walk(v,path+f'[{i}]')
    elif isinstance(x,str) and any(w in x for w in ['解读','nbs_review','需求不足','采购量']):
     found.append({'json_path':path,'value':x})
   walk(obj,n)
   info[n]={'status':obj.get('status'),'matched_source_or_cause_references':found}
 related.append(info)
# 候选本地原件仅按既有官方PMI解读文件命名定位，不扫全部数据内容。
raw_dirs=[ROOT/'data/raw/macro/510300_macro_stress_avoidance_v1_sources',
          ROOT/'data/raw/macro/510300_manufacturing_price_transmission_v1_sources']
raw_candidates=[]
for d in raw_dirs:
 if d.exists():
  for f in d.iterdir():
   if f.is_file() and any(w in f.name.lower() for w in ['review','interpret','jie','解读']):
    raw_candidates.append({'path':str(f.relative_to(ROOT)).replace('\\','/'),'bytes':f.stat().st_size})
obj={'study_id':proto['study_id'],'recorded_at':datetime.now(ZoneInfo('Asia/Shanghai')).isoformat(),
 'status':'BOUNDED_PRIOR_USE_LOCATORS_SOURCE_MEANING_PENDING',
 'command':cmd,'keyword_matches':matches,'related_study_entries':related,
 'local_named_interpretation_candidates':raw_candidates,
 'limits':'只定位已登记源码/配置和三直接研究入口；关键词出现不等于同用途，未穷尽全部历史版本。未查询账户凭据、未请求到期运输。'}
(OUT/'本地有限旧用途定位.json').write_text(json.dumps(obj,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print('有限关键词命中数',len(matches))
for x in matches[:35]:print(x['locator'][:550])
print('相关研究入口摘要')
for x in related:
 print(json.dumps({'directory':x['directory'],'files':x['files'],
                  **{k:v for k,v in x.items() if k.endswith('.json')}},ensure_ascii=False)[:5000])
print('本地命名解读候选数',len(raw_candidates))
for x in raw_candidates[:15]:print(x['path'])
